"""Plain-language surgical risk report generation.

Default behaviour is a template-based report — no external API key or
network call required, so the project runs end-to-end out of the box.

If you later want an LLM-polished version of the same report, set the
ANTHROPIC_API_KEY environment variable; ``build_report_text`` will use it
automatically and fall back to the template on any error.
"""

from __future__ import annotations

import os

from braintumor.risk.mapping import RiskRegion

DISCLAIMER = (
    "This report is generated by a research/educational prototype. Region "
    "locations are approximate (heuristic, not a validated brain atlas). "
    "This is NOT a medical device and must NOT be used for real surgical "
    "planning or clinical decisions. Always consult a qualified radiologist "
    "or neurosurgeon."
)


def _template_report(case_name: str, regions: list[RiskRegion], tumor_volume_mm3: float | None) -> str:
    lines = [f"Surgical Risk Mapping Report — {case_name}", ""]

    if tumor_volume_mm3:
        lines.append(f"Whole tumor volume: {tumor_volume_mm3:,.0f} mm^3")
        lines.append("")

    high = [r for r in regions if r.risk_tier == "High"]
    moderate = [r for r in regions if r.risk_tier == "Moderate"]
    low = [r for r in regions if r.risk_tier == "Low"]

    if high:
        lines.append("HIGH RISK — tumor overlaps these regions:")
        for r in high:
            lines.append(f"  - {r.region.title()} ({r.overlap_pct}% overlap): {r.function}.")
        lines.append("")

    if moderate:
        lines.append("MODERATE RISK — tumor is within 10 mm of these regions:")
        for r in moderate:
            lines.append(f"  - {r.region.title()} (~{r.distance_mm} mm away): {r.function}.")
        lines.append("")

    if low:
        lines.append("LOW RISK — tumor is more than 10 mm from these regions:")
        for r in low:
            dist = f"~{r.distance_mm} mm away" if r.distance_mm is not None else "distance not determined"
            lines.append(f"  - {r.region.title()} ({dist}): {r.function}.")
        lines.append("")

    if high:
        lines.append(
            "Summary: the tumor directly overlaps at least one functionally "
            "significant region. Surgical approach planning should account "
            "for expected deficits related to the affected function(s) above."
        )
    elif moderate:
        lines.append(
            "Summary: the tumor does not overlap any mapped region but lies "
            "close to at least one. Margins near these regions should be "
            "treated with extra care."
        )
    else:
        lines.append(
            "Summary: the tumor is not close to any of the mapped functional "
            "regions in this simplified analysis."
        )

    lines.append("")
    lines.append(DISCLAIMER)
    return "\n".join(lines)


def _llm_report(case_name: str, regions: list[RiskRegion], tumor_volume_mm3: float | None) -> str | None:
    """Optional: ask an LLM to write a more natural version of the same facts.

    Returns None (caller should fall back to the template) if no API key is
    configured or the call fails for any reason.
    """
    api_key = os.getenv("ANTHROPIC_API_KEY")
    if not api_key:
        return None

    try:
        import anthropic

        client = anthropic.Anthropic(api_key=api_key)
        region_lines = "\n".join(
            f"- {r.region}: overlap={r.overlap_pct}%, distance_mm={r.distance_mm}, "
            f"risk={r.risk_tier}, function={r.function}"
            for r in regions
        )
        prompt = (
            f"Write a short (under 200 words), plain-English surgical risk "
            f"summary for case '{case_name}' based on this structured data. "
            f"Do not invent numbers not given below. End with this exact "
            f"disclaimer on its own line: \"{DISCLAIMER}\"\n\n"
            f"Tumor volume: {tumor_volume_mm3} mm^3\n"
            f"Regions:\n{region_lines}"
        )
        response = client.messages.create(
            model="claude-sonnet-4-6",
            max_tokens=500,
            messages=[{"role": "user", "content": prompt}],
        )
        return "".join(b.text for b in response.content if hasattr(b, "text")).strip()
    except Exception:
        return None


def build_report_text(
    case_name: str,
    regions: list[RiskRegion],
    tumor_volume_mm3: float | None = None,
) -> str:
    """Build the final report text: LLM version if configured, else template."""
    llm_text = _llm_report(case_name, regions, tumor_volume_mm3)
    return llm_text if llm_text else _template_report(case_name, regions, tumor_volume_mm3)
